DO $$ BEGIN CREATE TYPE user_role AS ENUM ('site_admin','area_admin','collaborator','readonly'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE user_status AS ENUM ('pending','active','revoked'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS companies (id serial PRIMARY KEY, name text NOT NULL, normalized_name text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id serial PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, first_name text, last_name text, company_id integer REFERENCES companies(id), role user_role NOT NULL, status user_status NOT NULL DEFAULT 'pending', email_verified_at timestamptz, phone text, invite_channel text NOT NULL DEFAULT 'email', can_invite boolean NOT NULL DEFAULT false, projects jsonb NOT NULL DEFAULT '[]'::jsonb, meetings jsonb NOT NULL DEFAULT '[]'::jsonb, topics jsonb NOT NULL DEFAULT '[]'::jsonb, invite_token_hash text, invited_at timestamptz, invite_expires_at timestamptz, accepted_at timestamptz);
CREATE TABLE IF NOT EXISTS tasks (id serial PRIMARY KEY, subject text NOT NULL, description text NOT NULL DEFAULT '', owner text NOT NULL, collaborators jsonb NOT NULL DEFAULT '[]'::jsonb, recipients jsonb NOT NULL DEFAULT '[]'::jsonb, due text NOT NULL, source text NOT NULL, topic text NOT NULL, project text NOT NULL, recurring_meeting text NOT NULL, status text NOT NULL DEFAULT 'Open', created text NOT NULL, updates jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE INDEX IF NOT EXISTS tasks_owner_idx ON tasks(owner); CREATE INDEX IF NOT EXISTS tasks_scope_idx ON tasks(project, recurring_meeting, topic);
CREATE TABLE IF NOT EXISTS dimension_values (id serial PRIMARY KEY, type text NOT NULL, value text NOT NULL, UNIQUE(type,value));
CREATE TABLE IF NOT EXISTS sessions (id_hash text PRIMARY KEY, user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id); CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS login_tokens (token_hash text PRIMARY KEY, user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_tokens_user_idx ON login_tokens(user_id);
